solution.exercise.c:
#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
bool parse_decimal(const char*s,uint64_t*out){uint64_t n=0;for(;*s;s++){int d=isdigit((unsigned char)*s)?*s-'0':(tolower((unsigned char)*s)>='a'&&tolower((unsigned char)*s)<='f'?tolower((unsigned char)*s)-'a'+10:99);if(d>=3)return false;n=n*3+d;}*out=n;return true;}uint64_t to_decimal(const char*s){uint64_t n=0;parse_decimal(s,&n);return n;}

