assert(to_decimal("10")==3);assert(to_decimal("1")==1);assert(to_decimal("")==0);assert(to_decimal("xyz")==0);uint64_t parsed;assert(!parse_decimal("xyz",&parsed));assert(parse_decimal("10",&parsed)&&parsed==3);assert(to_decimal("22")==8);
assert(to_decimal("0")==0);
assert(to_decimal("1")==1);
assert(to_decimal("10")==3);
assert(to_decimal("102101")==307);
